const fixtures = [{"harness":"pi","native":"route-hit","name":"Pi alias owner","id":"route-hit"},{"harness":"omp","native":"route-hit","name":"OMP alias collision","id":"~sk1_WyJvbXAiLCJyb3V0ZS1oaXQiXQ"},{"harness":"omp","native":"2026-09-05T09-07-03-291Z_01a070d2-43fb-7360-aaba-a4ddf8d1deb0","name":"Shared UUID morning","id":"~sk1_WyJvbXAiLCIyMDI2LTA5LTA1VDA5LTA3LTAzLTI5MVpfMDFhMDcwZDItNDNmYi03MzYwLWFhYmEtYTRkZGY4ZDFkZWIwIl0"},{"harness":"omp","native":"2026-09-06T09-07-03-291Z_01a070d2-43fb-7360-aaba-a4ddf8d1deb0","name":"Shared UUID next day","id":"~sk1_WyJvbXAiLCIyMDI2LTA5LTA2VDA5LTA3LTAzLTI5MVpfMDFhMDcwZDItNDNmYi03MzYwLWFhYmEtYTRkZGY4ZDFkZWIwIl0"},{"harness":"omp","native":"2026-09-07T09-07-03-291Z_01a07264-131e-74a7-979a-1e763bf12b97","name":"Ordinary UUID","id":"~sk1_WyJvbXAiLCIyMDI2LTA5LTA3VDA5LTA3LTAzLTI5MVpfMDFhMDcyNjQtMTMxZS03NGE3LTk3OWEtMWU3NjNiZjEyYjk3Il0"},{"harness":"omp","native":"shadowed","name":"Short alias","id":"~sk1_WyJvbXAiLCJzaGFkb3dlZCJd"},{"harness":"omp","native":"shadowed-long","name":"Extended alias","id":"~sk1_WyJvbXAiLCJzaGFkb3dlZC1sb25nIl0"}];
const outcomes = [];
for (const fixture of fixtures) {
  await page.keyboard.press("Escape");
  await page.click(".session-item-name[title=" + JSON.stringify(fixture.id) + "]", {button:"right"});
  const ref = await page.$eval("button[data-copy]", e => e.getAttribute("data-copy"));
  const resolved = await page.evaluate(async value => { const response = await fetch("/api/sessions/resolve?id=" + encodeURIComponent(value)); return {status:response.status,data:await response.json()}; }, ref);
  if (resolved.status !== 200 || resolved.data.session.id !== fixture.id) throw new Error("Reference retargeted " + fixture.name);
  outcomes.push({name:fixture.name,id:fixture.id,browserRef:ref,resolvedId:resolved.data.session.id});
}
await page.keyboard.press("Escape");
await page.click("text/OMP alias collision", {button:"right"});
return outcomes;
